Se alguém ficar confuso sobre o porque ele usou WritableStream ao invés de um "Writable.toWeb", o motivo disso é porque quando você faz dessa maneira, você pode criar uma Writable settando direatamente o que ela faz no metódo write e no close. Para fins de teste, você pode criar sua própria writable stream e fazer a mesma conversão, mantendo o padrão entre o uso delas como nesse exemplo:

const createWritableStream = (res: ServerResponse<IncomingMessage> & {
  req: IncomingMessage;
}) => {
  const writeStream = new Writable({
    write(chunk, _, callback) {
      console.log(chunk)
      res.write(chunk)
      callback();
    },
    final(callback) {
      console.log('Close stream')
      res.end();
      callback();
    },
  })

  return writeStream;
}

